SELECT symbol, interval_code, open_time, close_time, closed, ingestion_source, created_at, updated_at, (close_transition_token IS NOT NULL) AS has_token FROM candle WHERE symbol IN ('XLMUSDT','PEPEUSDT','BTCUSDT') AND ((interval_code='1h' AND open_time IN ('2026-10-10 16:00:00','2026-10-10 17:00:00','2026-10-10 18:00:00')) OR (interval_code='5m' AND open_time IN ('2026-10-10 17:50:00','2026-10-10 17:55:00','2026-10-10 18:00:00')) OR (interval_code='1m' AND open_time BETWEEN '2026-10-10 17:57:00' AND '2026-10-10 18:02:00')) ORDER BY symbol, interval_code, open_time